V=../avatar/refs; H=/home/user/marketingskills/docs/content-video/assets/hosts
SET="Setting: a glass-walled meeting room on a high floor in soft daylight. Behind the floor-to-ceiling glass: a bright pearl-white overcast sky fills the upper part of the view, and low near the horizon there is a soft hazy panorama of a modern coastal city. A long dark walnut table with two compact broadcast microphones on low desk stands (no logos), a closed laptop, a notebook, a glass of water."
ST="Photorealistic photograph, not an illustration, full-frame camera, 35mm lens, shallow depth of field, natural skin texture, clean airy daylight colour grade. Vertical 9:16 frame. No readable text, no logos, no watermark."
VIT="the man from the reference photos: keep his identity exactly, same shaved bald head, same face shape, dark eyebrows and eyes, short dark stubble, same age and build; he wears the same black thick-rimmed acetate glasses as in the close-up reference and the outfit from his full-length reference: black fine-knit turtleneck under a charcoal-grey unstructured blazer"
G="the blonde woman from the reference photos: keep her identity exactly, same face, long straight light honey-blonde hair worn loose, outfit from her full-length reference: white tailored trouser suit with an ivory silk camisole, thin gold chain"
AIR="Composition: the whole upper 40 percent of the frame is empty bright sky behind the glass with nothing in it; the top of the head is below that line. Medium shot from the waist up, the person sits at the table behind the microphone."
g(){ /usr/bin/python3 gen.py "$@"; }
if [ "$1" = two ]; then
g o_two "$SET $ST Two people sit at the corner of the table in a relaxed friendly interview, both turned three-quarters to the camera, each with a microphone in front of them. On the left: $G; she sits gracefully and listens with a light smile. On the right: $VIT; he speaks calmly with one hand on the table. Wide shot: both are seen from the knees up in the lower 55 percent of the frame; the whole upper 40 percent of the frame is empty bright sky behind the glass." $H/host_G_face.jpg g2.jpg $V/office_solo.jpg v3.jpg vit_glasses_crop.jpg
else
g o_host "$SET $ST One person in the frame, the same room as in the wide reference photo. This is $G. She leans slightly toward her microphone, looks into the camera lens, lips slightly parted as if asking a question, warm attentive expression, hands resting on the table. $AIR" $H/host_G_face.jpg g2.jpg o_two.png &
g o_vit_a "$SET $ST One person in the frame, the same room as in the wide reference photo. This is $VIT. He faces the camera, looks into the lens, lips slightly parted as if answering a question, calm confident expression, both hands resting on the table near the microphone. $AIR" $V/office_solo.jpg v3.jpg vit_glasses_crop.jpg o_two.png &
g o_vit_b "$SET $ST One person in the frame, the same room as in the wide reference photo. This is $VIT. He sits turned three-quarters to the left, looks into the camera lens, lips slightly parted mid-sentence, one hand raised slightly in an explaining gesture, the laptop closed beside him. $AIR" $V/office_solo.jpg v3.jpg vit_glasses_crop.jpg o_two.png &
wait
fi
